import json, csv, pathlib
P=pathlib.Path(__file__).parent
talks=[]; items=[]; problems=[]; corrections=[]; areas={}
def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(record,pages,kind,title,notes,statement,reconstruction,cl,fate,status,refs,correct='correct with missing hypotheses',match='exact',verification='read the result',confidence='high',development='none',problem='',speaker=None,area='Topology'):
    n=1+sum(i['record']==record for i in items)
    d=dict(id=f'{1972 if record==288 else 1971}-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status='As of November 2026, '+status,literal_correctness=correct,publication_match=match,verification=verification,development=development,problem=problem,worth='',refs=refs,confidence=confidence)
    if speaker: d['speaker']=speaker
    items.append(d); areas[d['id']]=area
    return d['id']
def corr(page,place,reads,should,evidence,applies='both',kind='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=kind))
def save():
    for name,obj in [('talks',talks),('items',items),('problems',problems),('areas',areas)]:
        (P/(name+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    with (P/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(259,'1972-03-20','D. A. Kazhdan','P000424-P000426','Quillen’s finite-field calculation: plus construction and Adams operations',r'''Kazhdan explains the proof of the finite-field calculation announced by Gelfand in record 258. The argument passes from a classifying space through a homology-preserving modification to a homotopy fibre of an Adams operation, using Brauer lifting and an étale comparison. Fuchs interrupts on P000424; Kazhdan resumes on P000425. The catalogue's P000423--P000425 interval starts too early and omits the proof's final page. Several apparent finite-rank statements actually require stabilization; the asserted identification of a fixed subgroup with maps into a homotopy fibre is a substantive error.''')
item(259,'P000424-P000425','construction','Stable plus construction for finite-field K-theory',r'''For \(G_n=GL_n(\mathbb F_q)\), the notes enlarge \(K(G_n,1)\) to \(B_n\), kill the commutator subgroup, fill the resulting two-dimensional cycles, and write \(K_i(G_n)=\pi_i(B_n)\). The enlarged space is called an \(H\)-space.''',r'''Put \(G=\operatorname*{colim}_n GL_n(\mathbb F_q)\), and let \(E=[G,G]\), the stable elementary subgroup. The plus construction \(BG\to BG^+\) kills the perfect normal subgroup \(E\) and preserves integral homology, indeed homology with local coefficients pulled back from \(G/E\). For \(i\geq1\), \(K_i(\mathbb F_q)=\pi_i(BG^+)\). Block sum supplies the stable \(H\)-space structure. The construction can be made by attaching cells in dimensions two and three.''',r'''The stable group, the perfectness condition, and the distinction between attaching three-cells and ``three-cycles'' are supplied. No claim that a fixed finite \(n\) computes all higher \(K\)-groups is retained.''','B',r'''This is the construction underlying \citet{quillen1972finitefields}, published in 1972 after the March exposition by Kazhdan. The final finite-field calculation is indexed separately in record 258; the present occurrence records its topological mechanism.''',r'''the stable construction is standard. Fixed-rank spaces require a specified stability range, absent from the notebook.''',['quillen1972finitefields'],verification='publisher metadata checked',confidence='medium')
item(259,'P000425','construction','Adams operations represented on reduced complex K-theory',r'''The power sum \(\sum_i\lambda_i^k\) of eigenvalues of a unitary matrix is a virtual character. It defines \(\psi^k\) on bundles and hence a self-map of \(BU\); the notes write \(K^0(X)=[X,BU]\), with a marginal qualification about quotienting trivial bundles.''',r'''For a pointed connected finite CW complex, \(\widetilde K^0(X)\cong[X,BU]_*\); unreduced \(K^0\) is represented by \(\mathbb Z\times BU\). For \(k\geq1\), Newton polynomials in the exterior-power operations define a natural ring endomorphism \(\psi^k\), characterized on line bundles by \(\psi^k[L]=[L^{\otimes k}]\). The character on a rank-\(n\) bundle is the indicated power sum.''',r'''Reduced theory and a finite-CW domain are made explicit; a virtual representation need not be an actual bundle of nonnegative rank.''','E',r'''Adams operations were established before 1972 and are treated in \citet[Chapter II]{atiyah1967ktheory}. Kazhdan is using this existing apparatus in Quillen's calculation.''',r'''the construction and normalization remain standard; the rank component must be included for unreduced theory.''',['atiyah1967ktheory'],verification='publisher metadata checked')
item(259,'P000425-P000426','theorem','Finite-field K-theory as the fibre of an Adams operation',r'''The claim is \(E\psi^q=B_n=B\) ``for large \(n\)'', where \(E\psi^q\) is the fibre of \(\psi^q-1:BU\to BU\). Frobenius is identified with the topological Adams operation.''',r'''For a prime power \(q\), the stable space \(BGL(\mathbb F_q)^+\) has the homotopy type of \(\operatorname{hofib}(\psi^q-1:BU\to BU)\). Since \(\psi^q\) acts on \(\pi_{2j}(BU)\cong\mathbb Z\) by multiplication by \(q^j\), its fibre has \(\pi_{2j-1}\cong\mathbb Z/(q^j-1)\) and \(\pi_{2j}=0\) for \(j\geq1\).''',r'''``Fibre'' means homotopy fibre, and the equality is a homotopy equivalence after stabilization. The long exact homotopy sequence explains the numerical result rather than assuming a fixed-rank identification.''','B',r'''The result is the central geometric input of \citet{quillen1972finitefields}. Its publication later in 1972 is by Quillen, not by the seminar speaker. The contemporary seminar already knew the announced result.''',r'''the equivalence and resulting finite-field groups are established; the manuscript's finite-rank shorthand remains unsafe without a stability bound.''',['quillen1972finitefields'],verification='publisher metadata checked',confidence='medium')
item(259,'P000425','claim','A homotopy fibre does not represent the bare fixed subgroup',r'''The notes assert that \([K(X)]^k=\{\xi:\psi^k\xi=\xi\}\) is represented by \([X,E\psi^k]\), and call this easy to check.''',r'''Let \(F_k=\operatorname{hofib}(\psi^k-1:BU\to BU)\). For finite pointed CW complexes there is an exact sequence of abelian groups \[\widetilde K^{-1}(X)\xrightarrow{\psi^k-1}\widetilde K^{-1}(X)\longrightarrow[X,F_k]_*\longrightarrow\widetilde K^0(X)\xrightarrow{\psi^k-1}\widetilde K^0(X).\] Thus a map into \(F_k\) includes a chosen homotopy from \(\psi^k\xi\) to \(\xi\). For \(X=S^1\) and \(k>2\), the fixed subgroup in reduced degree zero is zero, whereas \([S^1,F_k]_*\cong\mathbb Z/(k-1)\).''',r'''The exact sequence and the circle counterexample are an editorial check of the literal assertion. They use \(\psi^k\) acting by \(k\) on \(\widetilde K^{-1}(S^1)\cong\widetilde K^0(S^2)\).''','E',r'''The distinction follows from the ordinary homotopy-fibre sequence and the pre-existing Adams-operation formalism in \citet{atiyah1967ktheory}. It is not an unresolved part of Quillen's theorem.''',r'''the literal representability statement is false; retaining the null-homotopy data repairs it.''',['atiyah1967ktheory'],correct='false as written',match='partial',verification='indirect',development='annotated')
item(259,'P000426','method','Brauer lifting and Frobenius invariance',r'''Choose \(\mu:\overline{\mathbb F}_q^*\to\mathbb C^*\), form \(\varphi_\mu(g)=\sum_i\mu(\lambda_i)\), and invoke Brauer's theorem to obtain a virtual character. The equality of the multisets \(\{\lambda_i\}\) and \(\{\lambda_i^q\}\) gives Adams invariance; a map is then extended over the added cells.''',r'''Choose compatible lifts of roots of unity of order prime to \(p=\operatorname{char}\mathbb F_q\). Brauer lifting of the defining representation produces a stable map to complex \(K\)-theory. Frobenius invariance is the relation used to lift this map to the homotopy fibre of \(\psi^q-1\). For a unipotent matrix of size \(n\), the displayed sum of eigenvalue lifts equals \(n\), not \(1\); the corresponding reduced class has rank zero.''',r'''The Brauer character, its stable realization, and the coherent homotopy required for the fibre lift must be distinguished. The manuscript's pointwise character argument alone does not construct that coherence or justify extension across every cell.''','B',r'''Brauer lifting forms part of the proof in \citet{quillen1972finitefields}. The eigenvalue observation is recognizable, but the notebook compresses the comparison construction too far to serve as a complete proof.''',r'''the method is established. The claim \(\varphi_\mu=1\) on unipotents is incompatible with the displayed unnormalized rank-\(n\) formula.''',['quillen1972finitefields'],correct='false as written',match='partial',verification='publisher metadata checked',confidence='medium')
item(259,'P000426','method','The Lang map and étale comparison',r'''To compute the homology of \(K(G_n,1)\), the notes propose \(g\mapsto g^{-1}g^\sigma\), with \(\sigma\) Frobenius, followed by the spectral sequence of a fibration.''',r'''For a connected algebraic group \(G\) over \(\mathbb F_q\), the Lang map \(L(g)=g^{-1}F(g)\) is surjective and, for smooth \(G\), is a finite étale torsor under the finite group \(G(\mathbb F_q)\) acting on the left. Applied to general linear groups, it gives an étale analogue of the fibration used in the comparison with the Adams-operation fibre. A cohomological comparison requires coefficients prime to \(p\), followed by the separate treatment implicit in the finite-field theorem.''',r'''The connectedness, smoothness and prime-to-characteristic qualifications are supplied. The spectral sequence is a method, not an explicit calculation recorded on this page.''','B',r'''The application to finite-field \(K\)-theory is developed in \citet{quillen1972finitefields}; the Lang map itself predates the talk. This occurrence is classified by its use in the new calculation.''',r'''the method is standard; the manuscript does not specify enough terms or differentials to reconstruct its entire spectral sequence independently.''',['quillen1972finitefields'],match='partial',verification='publisher metadata checked',confidence='medium')
corr('P000424-P000425','Quillenization and H-space','K_i(G_n)=pi_i(B_n); B_n is an H-space','Use the stable group GL(F_q) and its plus construction; fixed rank requires a stability range.','The notes use finite n throughout and then say large n. The stable construction is necessary for all degrees.');
corr('P000425','fixed subgroup represented by fibre','[K(X)]^k=[X,E psi^k]','Maps into the homotopy fibre also contain a null-homotopy; use the long exact sequence.','The scanned formula is literal; X=S^1 and k>2 gives a nonzero Z/(k-1) on the right and zero on the left.');
corr('P000426','unipotent value','phi_mu=1 on unipotents','The displayed sum is n on rank-n unipotents; the reduced value is zero.','All eigenvalues of a unipotent matrix are 1, and mu(1)=1.');save()

talk(260,'1972-03-20','D. B. Fuchs','P000424','When abelianizing the fundamental group preserves integral homology',r'''Fuchs inserts an existence theorem into Kazhdan's discussion: the commutator subgroup must be relatively perfect. He distinguishes existence from uniqueness and then invokes simple spaces and Whitehead's theorem. All of the identifiable intervention is on P000424, not throughout the catalogue's P000423--P000427 range.''')
item(260,'P000424','theorem','Relative perfectness and homology-preserving abelianization',r'''The condition is \([\pi_1X,\pi_1X]=[\pi_1X,[\pi_1X,\pi_1X]]\). It is said to be necessary and sufficient for a map \(X\to Y\) inducing integral homology isomorphisms with \(\pi_1Y\) abelian.''',r'''For a connected CW complex \(X\), write \(G=\pi_1X\) and \(N=[G,G]\). There is a CW complex \(Y\) and a map \(f:X\to Y\) inducing the quotient \(G\to G/N\) and an isomorphism on integral homology if and only if \([G,N]=N\). The space can be constructed by attaching two- and three-cells. This is relative perfectness, which is weaker than the perfect-kernel hypothesis \([N,N]=N\) for an acyclic plus construction.''',r'''Surjectivity and the specified quotient on fundamental groups are made explicit. Ordinary integral homology equivalence must not be silently strengthened to an acyclic map with all local coefficients.''','B',r'''The exact criterion appears in \citet[Corollary 4.3]{ye2012unified}; its preprint circulated in 2011 and the journal article appeared in 2012. That later verification does not establish priority for the 1972 oral statement. The attached erratum concerns a different application, not this corollary.''',r'''the criterion is established. Confusing relative perfectness with perfectness would wrongly reject the notebook's formula.''',['ye2012unified'],correct='correct',confidence='high')
item(260,'P000424','claim','Simple targets and the limits of the uniqueness assertion',r'''After saying the target \(Y\) need not be unique, Fuchs adds that a simple target is unique, citing Whitehead's theorem; he recalls that an \(H\)-space is simple.''',r'''A path-connected \(H\)-space is simple: its fundamental group is abelian and acts trivially on higher homotopy groups. A homology equivalence between connected simple CW complexes is a weak homotopy equivalence. This criterion proves uniqueness only after a comparison map between the proposed targets has been constructed; simplicity by itself is not the missing universal property of the preceding existence construction.''',r'''The first two assertions are standard precise statements. The notes do not specify the category of target maps, a universal property, or the comparison map needed to infer uniqueness; that inference is therefore left unresolved rather than identified with the usual plus-construction uniqueness theorem.''','F',r'''The homotopy-theoretic ingredients are classical; the cited Whitehead principle is discussed in \citet[Chapters 10 and 15]{may1999concise}. No exact publication matching this particular uniqueness formulation was identified in the searches for Fuchs, simple targets and homology localization.''',r'''the elementary ingredients are established, but the exact uniqueness assertion recoverable from this intervention remains under-specified; this is not a claim of an open problem.''',['may1999concise'],correct='not determinable',match='partial',verification='indirect',confidence='medium')
save()

talk(261,'1972-03-20','M. Sh. Birman','P000427','Trace-class perturbations and Gelfand’s spectral classification question',r'''Birman begins a stationary proof of the Kato--Rosenblum theorem and identifies two boundary-value facts used in it. Gelfand asks which prescribed spectral types can be realized with a trace-class difference, and what the spectrum in the corresponding operator quotient means. The next dated heading, Kazhdan on 27 March, begins at the bottom of this same page.''')
item(261,'P000427','theorem','The Kato–Rosenblum theorem',r'''If \(H,H_0\) are self-adjoint and \(V=H-H_0\) is nuclear, their absolutely continuous parts are unitarily equivalent.''',r'''Let \(H_0\) be self-adjoint on a separable Hilbert space and let \(V=V^*\in\mathcal S_1\) be bounded trace class. Set \(H=H_0+V\) on \(D(H_0)\). The wave operators \(W_\pm(H,H_0)\) exist and are complete, and intertwine the restrictions to the absolutely continuous spectral subspaces. Thus the absolutely continuous spectral measures and multiplicity functions agree up to unitary equivalence.''',r'''A common-domain bounded-perturbation formulation is supplied. The conclusion does not assert equivalence of the singular spectral parts.''','E',r'''The trace-class theorem predates the talk. A stationary proof with precisely this hypothesis is given by \citet[Theorem 1, Section 3]{birmanentina1967stationary}; Section 5 identifies the stationary and time-dependent wave operators.''',r'''the theorem is standard; trace-class control is a sufficient condition for complete scattering, not a classification of singular spectra.''',['birmanentina1967stationary'],correct='correct')
id261q=item(261,'P000427','question','Which spectral types admit trace-class-close realizations?',r'''Gelfand asks how to decide from a collection of spectral types whether realizations can be chosen whose difference is nuclear.''',r'''Given two unitary-equivalence classes of bounded self-adjoint operators \(A\) and \(B\) on separable Hilbert spaces of the same dimension, characterize the existence of a unitary \(U\) for which \(A-UBU^*\in\mathcal S_1\). The data must include spectral multiplicity, not merely the closed spectral sets. The Kato--Rosenblum theorem gives equality of the absolutely continuous parts as a necessary condition; it alone does not settle the question.''',r'''Boundedness and the unitary-equivalence formulation make the phrase ``collection of spectral types'' precise. The notes do not say whether unbounded operators, a prescribed trace norm, or exact singular spectral measures are intended.''','B',r'''The later paper \citet{careypincus1976traceclass} addresses unitary equivalence modulo trace class for self-adjoint operators. Its 1976 publication is verified bibliographically; the full classification theorem was not read in this audit, so no unverified necessary-and-sufficient criterion is quoted and no exact match to all possible unbounded interpretations is claimed.''',r'''a dedicated later classification exists for this operator-equivalence problem. The precise theorem hypotheses and the full reach of the notebook's wording still require full-text verification; this is not evidence that the bounded problem remains open.''',['careypincus1976traceclass'],correct='correct with missing hypotheses',match='partial',verification='publisher metadata checked',confidence='medium',problem='GP-1971-40',speaker='I. M. Gelfand',area='Operator theory')
problems.append(dict(id='GP-1971-40',title='Unitary equivalence modulo trace class from spectral data',statement=r'''For bounded self-adjoint operators \(A,B\) on separable Hilbert spaces, characterize from their spectral measures and multiplicities whether \(A-UBU^*\in\mathcal S_1\) for some unitary \(U\).''',occurrences=[id261q],status=r'''November 2026: the dedicated classification paper of \citet{careypincus1976traceclass} was identified and its publication verified. Its theorem text was not available in this audit, so the exact criterion and any unbounded extension are not asserted. No earlier exact occurrence was found in the supplied index.''',status_date='2026-11',refs=['careypincus1976traceclass']))
item(261,'P000427','question','Spectrum in the algebraic quotient by trace-class operators',r'''Gelfand asks: ``Spectrum in the quotient ring modulo the nuclear operators --- ?''',r'''For a bounded operator \(T\) on an infinite-dimensional Hilbert space, define the spectrum of its coset in the unital algebra \(\mathcal B(\mathcal H)/\mathcal S_1\) algebraically, using two-sided invertibility. This spectrum equals the Fredholm essential spectrum. Indeed an inverse modulo \(\mathcal S_1\) is an inverse modulo compact operators; conversely a Fredholm operator has a parametrix with finite-rank errors, hence trace-class errors.''',r'''This is one precise natural reading of the question, not a reconstruction of a proposed new invariant. The quotient is not a Banach algebra for the operator-norm quotient topology because \(\mathcal S_1\) is not operator-norm closed.''','E',r'''The argument is the classical Fredholm-parametrix criterion, already available before the talk; it is included as an elementary editorial clarification of what the quotient-ring spectrum can and cannot distinguish. The surrounding scattering context is documented in \citet{birmanentina1967stationary}.''',r'''under this algebraic interpretation the answer is the essential spectrum. A finer trace-class invariant would require additional structure beyond ordinary quotient-algebra invertibility.''',['birmanentina1967stationary'],match='thematic only',verification='indirect',development='annotated',speaker='I. M. Gelfand',area='Operator theory')
item(261,'P000427','theorem','Sandwiched spectral derivatives and resolvent boundary values',r'''For Hilbert--Schmidt operators \(D_1,D_2\), the derivative of \(D_1E_\lambda D_2\) is nuclear almost everywhere, and \(D_1R_{\lambda+i\varepsilon}D_2\) has an almost-everywhere Hilbert--Schmidt boundary value as \(\varepsilon\downarrow0\).''',r'''Let \(H\) be self-adjoint with spectral resolution \(E_\lambda\), and let \(D_1,D_2\in\mathcal S_2\). The \(\mathcal S_1\)-valued bounded-variation spectral distribution has an almost-everywhere derivative in trace norm. The sandwiched resolvent has almost-everywhere limits in \(\mathcal S_2\) along the upper or lower half-plane. These are operator-valued boundary statements; they do not assert an unsandwiched norm limit for \((H-\lambda\mp i0)^{-1}\).''',r'''The topology of convergence, the almost-everywhere qualification and the use of a sandwiched spectral measure are made explicit.''','E',r'''These are the auxiliary stationary-scattering facts developed in \citet[Section 2]{birmanentina1967stationary}. The notes correctly identify the Hilbert--Schmidt rigging that makes them usable.''',r'''the facts remain standard tools for the stationary trace-class method.''',['birmanentina1967stationary'],correct='correct',area='Operator theory')
item(261,'P000427','method','A stationary formula for the intertwining operator',r'''An integral of the derivative of \((E_\lambda(I+VR_z^0)f,g)\), evaluated at \(z=\lambda\pm i0\), is proposed for \((W_\pm f,g)\). The perturbation \(V\) is factored into two Hilbert--Schmidt operators.''',r'''For a self-adjoint trace-class perturbation, factor \(V\) through \(\mathcal S_2\), use boundary values of the sandwiched resolvents to define stationary wave operators on the absolutely continuous subspace, and extend by zero on its orthogonal complement. The resulting operators are partial isometries with initial space \(\mathcal H_{\rm ac}(H_0)\) and final space \(\mathcal H_{\rm ac}(H)\).''',r'''The notebook integral is a schematic weak formula: spectral-density differentiation, boundary evaluation and integration cannot be interchanged without the factorization estimates. The precise construction, rather than a falsely pointwise formula for every vector, is the modern statement.''','E',r'''The construction is explicit in \citet[Section 3, formula (3.17) and Theorem 1]{birmanentina1967stationary}, five years before this talk.''',r'''the stationary construction and its equivalence to time-dependent scattering are established.''',['birmanentina1967stationary'],match='partial',area='Operator theory')
save()

talk(262,'1972-03-27','D. A. Kazhdan','P000427-P000428','Artin–Mazur étale homotopy and arithmetic symmetry',r'''Kazhdan outlines an algebraic construction of the homotopy type of a variety, its comparison over the complex numbers, and the action of field automorphisms. The completion paragraph runs onto P000428. The ordinary-space terminology in the notes suppresses the pro-homotopy category essential to Artin--Mazur's formulation.''')
item(262,'P000427','construction','Étale homotopy type and complex comparison',r'''An algebraic \(X\) over any field produces a complex \(C_X\); over \(\mathbb C\) it is the completion of the ordinary complex space.''',r'''For a locally noetherian scheme \(X\), the étale hypercover construction produces a pro-object in the homotopy category of simplicial sets, its étale homotopy type. For a scheme of finite type over \(\mathbb C\), its profinite étale homotopy type is compared with the profinite completion of the analytic homotopy type, under the usual comparison hypotheses. It is not in general a single CW complex with the same integral homotopy groups as \(X(\mathbb C)\).''',r'''``Set over a field'' is interpreted as a scheme; finite-type and pro-object qualifications are supplied. The passage to profinite completion is retained rather than strengthening the comparison to uncompleted spaces.''','E',r'''\citet[Chapters 9--12]{artinmazur1969etale} developed the hypercover construction and comparison before the 1972 talk; the monograph appeared in 1969.''',r'''the construction is a foundation of étale homotopy theory. The notebook's shorthand is recognizable but not a complete theorem statement.''',['artinmazur1969etale'],verification='publisher metadata checked',confidence='medium',area='Algebraic geometry')
item(262,'P000427','construction','Galois action on geometric étale homotopy',r'''Field automorphisms preserving \(X\) act on \(C_X\); for a variety defined over \(\mathbb Q\), the group is written \(\operatorname{Gal}(\mathbb C\mid\mathbb Q)\).''',r'''If \(X\) is defined over a field \(k\) with separable closure \(\bar k\), functoriality gives a homotopy-coherent action of \(\operatorname{Gal}(\bar k/k)\) on the geometric étale homotopy type of \(X_{\bar k}\). For pointed homotopy groups, a geometric point and base-point transport are required; the fundamental-group action is naturally outer until those choices are made.''',r'''The arithmetic Galois group and the distinctions between a functorial action, an action on a chosen model, and an outer action on a fundamental group are made explicit. The huge abstract automorphism group of \(\mathbb C\) is not treated as a group of continuous automorphisms of the analytic space.''','E',r'''This arithmetic functoriality is part of the Artin--Mazur construction \citep{artinmazur1969etale}. No new Galois-action conjecture is posed here.''',r'''Galois actions on geometric étale homotopy types are established; the model and base-point qualifications remain essential.''',['artinmazur1969etale'],match='partial',verification='publisher metadata checked',confidence='medium',area='Algebraic geometry')
item(262,'P000428','construction','Completion is represented in a pro-homotopy category',r'''The notes collect maps from \(X\) to spaces with finite homotopy groups and say that a compatible mapping functor is represented by \(\widehat X\).''',r'''Profinite homotopy completion is characterized by maps into finite homotopy types, ordinarily meaning spaces with finitely many components, finitely many nonzero homotopy groups and each homotopy group finite. The universal object belongs to a pro-homotopy category. Maps from a test object into an inverse system and maps from an inverse system into a test object have different limit/colimit formulas; they must not be conflated.''',r'''The finite-type test category and pro-representability are a reconstruction. The notebook's product of compatible \(\operatorname{Hom}(Y,X_i)\) describes maps to a given pro-system, not by itself the universal construction of the completion of \(X\).''','E',r'''Completions and pro-objects are developed in \citet[Chapters 2--3]{artinmazur1969etale}, predating this exposition.''',r'''the pro-categorical formulation is standard. Ordinary representability by one cell complex is not justified by the text.''',['artinmazur1969etale'],match='partial',verification='publisher metadata checked',confidence='medium')
corr('P000427-P000428','Artin–Mazur complex and completion','An ordinary complex C_X; the compatible functor is representable','Retain the étale homotopy pro-object and profinite comparison; specify the pro-category.','The notes omit the ambient pro-homotopy category required by Artin–Mazur.');save()

talk(264,'1972-03-27','I. M. Gelfand','P000428','A reading plan for the seminar’s common categorical language',r'''Gelfand asks participants to learn categories and functors from the first chapter of Grothendieck's Tohoku paper, then topoi and descent from the material accompanying Mumford. This is a reading plan, with no separately stated theorem. It precedes Birman's continuation on the page, although its catalogue record number is later. The plan connects the earlier site and sheaf discussions (for example 1967-143 and 1970-226) to Geronimus's April lectures.''',kind='plan')
save()

talk(263,'1972-03-27','M. Sh. Birman','P000428-P000430','Stationary and time-dependent wave operators',r'''Birman continues the trace-class scattering proof, explains completeness through reverse wave operators and the chain rule, and derives a resolvent identity controlling spectral densities. He explicitly refers to the 1967 Izvestiya paper. A final sketch gestures toward locally trace-class perturbations and unbounded operators; its missing domain hypotheses are retained as a limitation.''')
item(263,'P000428-P000429','theorem','Time-dependent wave operators, intertwining and completeness',r'''The strong limits \(W_\pm=\lim_{t\to\pm\infty}e^{itH}e^{-itH_0}P_0\) are defined, with \(P_0\) the absolutely continuous projection. The notes state \(W_\pm H_0=HW_\pm\) and say completeness is equivalent to existence of the reverse wave operator.''',r'''For self-adjoint \(H,H_0\), if the indicated strong limit exists, it is an isometry on \(\mathcal H_{\rm ac}(H_0)\), vanishes on its orthogonal complement, and intertwines bounded Borel functions of the operators. It is complete precisely when the corresponding reverse wave operator exists and has adjoint \(W_\pm(H,H_0)^*\). Under the common-domain trace-class perturbation hypothesis, existence holds in both directions and hence completeness follows.''',r'''The adjoint relation and the spectral-projection meaning of the unbounded intertwining identity are supplied. Existence alone is not completeness for arbitrary nonsymmetric hypotheses.''','E',r'''These are established scattering-theory facts; \citet[Sections 1 and 5]{birmanentina1967stationary} give the stationary/time-dependent comparison used in the talk.''',r'''the statements are standard with the stated absolutely continuous projections and domains.''',['birmanentina1967stationary'],area='Operator theory')
item(263,'P000429','theorem','The chain rule for wave operators',r'''The displayed composition is \(W_\pm(H_3,H_2)W_\pm(H_2,H_1)=W_\pm(H_3,H_1)\).''',r'''If the two wave operators on the left exist, their product gives the direct wave operator provided the range of \(W_\pm(H_2,H_1)\) lies in the absolutely continuous subspace of \(H_2\), as it does for ordinary wave operators of self-adjoint operators. In particular the rule applies to complete wave operators; completeness of both factors implies completeness of the product.''',r'''A fixed common sign is required. The insertion of the intermediate absolutely continuous projection is the point that makes the strong-limit multiplication legitimate.''','E',r'''The chain rule belongs to the general wave-operator framework summarized in \citet[Section 1]{birmanentina1967stationary}; it is not a new consequence first obtained in 1972.''',r'''the chain rule remains valid in this setting and is frequently used to reduce perturbation comparisons to intermediate operators.''',['birmanentina1967stationary'],correct='correct',area='Operator theory')
item(263,'P000429-P000430','method','Resolvent factorization and spectral localization of the stationary formula',r'''With \(Q_z=I+VR_z^0\), Birman writes \(R_z^0-R_{\bar z}^0=Q_z^*(R_z-R_{\bar z})Q_z\). The upper integration bound \(\sigma\) gives \((E_\sigma W_\pm f,g)\), and the construction is independent of the Hilbert--Schmidt factorization of \(V\).''',r'''For \(R_z=(H-z)^{-1}\), \(R_z^0=(H_0-z)^{-1}\) and \(V=H-H_0\), the resolvent identity gives \(R_zQ_z=R_z^0\). Combining this with \(R_z-R_{\bar z}=(z-\bar z)R_z^*R_z\) proves the displayed identity. After Hilbert--Schmidt sandwiching and taking almost-everywhere boundary values, it identifies the absolutely continuous spectral densities and proves that the stationary partial isometry respects spectral projections. Uniqueness of the resulting weak form yields independence of the factorization.''',r'''The formula is checked with the notes' resolvent convention. A density statement is made only after rigging; it is not an operator-norm identity for unsandwiched boundary resolvents.''','E',r'''The argument is the stationary proof in \citet[Section 3, Theorem 1]{birmanentina1967stationary}, the paper explicitly named in the notebook.''',r'''the derivation is established and the resolvent identity is correct with this convention.''',['birmanentina1967stationary'],correct='correct',area='Operator theory')
item(263,'P000430','claim','The incompletely stated local trace-class extension',r'''The ``more general variant'' asks for \(E(\Delta)(H-H_0)E_0(\Delta)\in\mathcal S_1\), followed by a comparison of domains of growing functions of \(H\) and \(H_0\). The inclusion sign and the functions are not fully resolved.''',r'''The recoverable idea is to localize a perturbation between spectral projections and obtain wave operators on the corresponding energy intervals. The notebook does not specify which intervals \(\Delta\), whether the difference is an operator or a quadratic form, how the domains are compared, or the additional conditions guaranteeing isometry and completeness. Consequently no single full theorem is asserted from these two lines.''',r'''Only the method and its missing quantifiers are reconstructed. A global trace-class theorem cannot simply be substituted for this local statement.''','F',r'''\citet{birman1968local} is an exact topical lead: its abstract distinguishes local weak existence, isometry and completeness, and its publication predates the talk. Metadata were checked, but the theorem text was not successfully retrieved, so the notebook variant is not claimed to match any numbered theorem.''',r'''local trace-class scattering criteria are established. Identification of the specific variant on this page remains incomplete, rather than mathematically open.''',['birman1968local'],correct='not determinable',match='partial',verification='publisher metadata checked',confidence='medium',area='Operator theory')
