byid={i['id']:i for i in items}
z=byid['1971-261.4']
z['statement']=r'''Let \(H\) be self-adjoint with spectral resolution \(E\), and let \(D_1,D_2\in\mathcal S_2\). The function \(\lambda\mapsto D_1E(( -\infty,\lambda])D_2\) has bounded variation in \(\mathcal S_1\) and an almost-everywhere derivative in trace norm. For almost every real \(\lambda\), the sandwiched resolvents \(D_1(H-\lambda\mp i\varepsilon)^{-1}D_2\) have limits in \(\mathcal S_2\) as \(\varepsilon\downarrow0\). These statements do not assert an unsandwiched norm limit for the resolvent.'''
z=byid['1971-263.2']
z['statement']=r'''Let \(H_1,H_2,H_3\) be self-adjoint on the same Hilbert space, and use the ordinary wave operators \(W_\pm(H_j,H_i)=\operatorname*{s-lim}_{t\to\pm\infty}e^{itH_j}e^{-itH_i}P_{\rm ac}(H_i)\). If \(W_\pm(H_3,H_2)\) and \(W_\pm(H_2,H_1)\) exist for a fixed sign, then \(W_\pm(H_3,H_1)\) exists and equals their product. The range of the second factor lies in \(\mathcal H_{\rm ac}(H_2)\), which permits insertion of the intermediate projection. Completeness of both factors implies completeness of the product.'''
z=byid['1971-263.3']
z['statement']=r'''Let \(H_0\) be self-adjoint, \(V=V^*\in\mathcal S_1\), and \(H=H_0+V\) on \(D(H_0)\). For \(z\notin\mathbb R\), put \(R_z=(H-z)^{-1}\), \(R_z^0=(H_0-z)^{-1}\), and \(Q_z=I+VR_z^0\). The resolvent identity gives \(R_zQ_z=R_z^0\). Combining this with \(R_z-R_{\bar z}=(z-\bar z)R_z^*R_z\) gives \(R_z^0-R_{\bar z}^0=Q_z^*(R_z-R_{\bar z})Q_z\). After Hilbert--Schmidt sandwiching and almost-everywhere boundary passage, this identifies the absolutely continuous spectral densities and makes the stationary partial isometry respect spectral projections. Uniqueness of the resulting weak form yields independence of the factorization.'''
z=byid['1971-265.7']
z['fate']+=r''' The earlier site formulation is also explicit in \citet[Chapter II, Theorem 4.11]{artin1962topologies}, read in the 1962 primary notes.'''
z['refs'].append('artin1962topologies')
z=byid['1971-265.9']
z['statement']=r'''The constant sheaf \(\underline A\) is the sheafification of the constant presheaf with value \(A\). Let \(F\to E\to B\) be a Serre fibration with connected CW base and fibre of CW type, and let \(k\) be a field. Its cohomology spectral sequence has \(E_2^{p,q}=H^p(B;\mathcal H^q(F;k))\), where monodromy defines the coefficient system. If monodromy on each \(H^q(F;k)\) is trivial and each such vector space is finite dimensional, then \(E_2^{p,q}\cong H^p(B;k)\otimes_k H^q(F;k)\).'''
z['reconstruction']+=r''' Finite-dimensional fibre cohomology in every degree is one explicit sufficient condition for the tensor identification.'''
byid['1971-266.1']['reconstruction']=byid['1971-266.1']['reconstruction'].replace('unsiged','unsigned')

